/**
 * NeuroGlove 3D Hand Anatomy Atlas
 * Interactive multi-layer volumetric anatomical model with real-time dissection,
 * innervation mapping, and rehabilitation sensor correlation.
 */

(function () {
    'use strict';

    const IM = {
        palm: "data:image/webp;base64,",
        dorsal: "data:image/webp;base64,"
    };

    const W = 1400, H = 1800, U = 0.0135, T = 1.3, K = 2.8;

    const R = {
        palm: {
            m: [
                ['Adductor pollicis', 225, 290, 305, 385, 'Draws the thumb toward the palm; vital for pinch and grip. Innervation: Ulnar nerve (deep branch). Correlates with NeuroGlove Flex 1 & Palmar FSR.'],
                ['Forearm flexor muscle bellies', 90, 520, 300, 660, 'Flexor digitorum superficialis/profundus and flexor pollicis longus bellies. Flexes fingers and thumb; tendons pass through carpal tunnel. Innervation: Median & anterior interosseous nerves.'],
                ['Hypothenar muscles', 55, 340, 150, 500, 'Abductor, flexor, and opponens digiti minimi. Controls little finger opposition and cups the palm. Innervation: Ulnar nerve (deep branch). Correlates with Flex 5.'],
                ['Thenar muscles', 150, 370, 345, 510, 'Abductor pollicis brevis, flexor pollicis brevis, and opponens pollicis forming the thenar eminence. Controls thumb opposition and grip. Innervation: Median nerve (recurrent branch). Correlates with Flex 1.']
            ],
            c: [
                ['Articular cartilage (finger joints)', 0, 0, 330, 335, 'Smooth hyaline cartilage on heads of metacarpals and phalanges (MCP, PIP, DIP joints), providing low-friction gliding during flexion.'],
                ['Synovial sheath / wrist cartilage', 0, 335, 500, 660, 'Synovial sheaths enveloping flexor tendons within the carpal canal and radiocarpal articulation, minimizing friction during wrist motions.']
            ],
            b: [
                ['Flexor retinaculum (transverse carpal ligament)', 95, 455, 265, 515, 'Thick fibrous band bridging the carpal arch, forming the roof of the carpal tunnel. Transmits flexor tendons and median nerve. Tracked by wrist IMU.'],
                ['Palmar aponeurosis', 80, 320, 285, 458, 'Dense triangular fascia overlying central palm. Anchors palmar skin and protects neurovascular bundles. Correlates with palmar FSR force sensing.'],
                ['Thumb bones & flexor pollicis longus tendon', 285, 235, 445, 345, 'First metacarpal, proximal and distal phalanges with FPL tendon bending the thumb tip. Correlates with Flex Sensor 1.'],
                ['Finger bones & flexor tendons', 30, 0, 300, 322, 'Phalanges of digits 2-5 with flexor digitorum superficialis & profundus tendons powering grasp. Correlates with Flex Sensors 2-5.'],
                ['Forearm bones & flexor tendons', 0, 515, 500, 660, 'Distal radius and ulna with long flexor tendons entering the hand. Tracked by wrist orientation IMU.'],
                ['Bones & tendons', 0, 0, 500, 660, 'Rigid osseous scaffold of the human hand with tendinous insertions translating muscle contractions into articulated grasping forces.']
            ],
            s: [
                ['Skin & subcutaneous tissue', 0, 0, 500, 660, 'Glabrous palmar skin rich in Meissner and Pacinian corpuscles, epidermal ridges, and dense subcutaneous fat pads optimized for tactile sensation and non-slip grasp.']
            ]
        },
        dorsal: {
            m: [
                ['First dorsal interosseous & adductor pollicis', 110, 300, 200, 425, 'Strongest intrinsic muscle of the hand; abducts index finger and powers key-pinch grip. Innervation: Ulnar nerve (deep branch). Correlates with Flex 2.'],
                ['Dorsal interossei', 185, 280, 345, 430, 'Four bipennate muscles between metacarpals; abduct fingers away from middle finger axis (DAB). Innervation: Deep branch of ulnar nerve.'],
                ['Forearm extensor muscle bellies', 0, 500, 500, 660, 'Extensor digitorum, extensor pollicis longus/brevis, and extensor carpi bellies straightening wrist and fingers. Innervation: Radial nerve (posterior interosseous).']
            ],
            c: [
                ['Extensor tendon synovial sheaths', 0, 360, 360, 600, 'Fluid-filled synovial compartments under the extensor retinaculum preventing tendon fraying during finger extension.'],
                ['Articular cartilage (finger joints)', 0, 0, 400, 360, 'Dorsal capsule and articular cartilage covering MCP and IP joints, supporting hyperextension stability.']
            ],
            b: [
                ['Extensor retinaculum', 150, 480, 340, 585, 'Strong fibrous band divided into six dorsal compartments holding extensor tendons against the distal radius and ulna.'],
                ['Phalanges & extensor hood', 120, 0, 365, 285, 'Dorsal aponeurosis (extensor expansion) integrating extensor digitorum, lumbrical, and interosseous slips to coordinate knuckle flexion with IP joint extension.'],
                ['Thumb metacarpal & phalanges', 20, 260, 160, 440, 'Thumb skeletal ray with extensor pollicis longus & brevis tendons. Correlates with Flex 1 extension tracking.'],
                ['Metacarpals & extensor tendons', 120, 270, 360, 440, 'Metacarpal shafts 2-5 with long extensor tendons crossing dorsal surface. Tracked across hand span.'],
                ['Carpal bones & wrist extensor tendons', 120, 430, 360, 660, 'Scaphoid, lunate, triquetrum, hamate, capitate, trapezoid, trapezium, and wrist extensors. Tracked by wrist 6-DoF IMU.']
            ],
            s: [
                ['Skin & subcutaneous tissue', 0, 0, 500, 660, 'Thin, highly mobile dorsal skin allowing full fist closure without tension; dorsal venous network visible.']
            ]
        }
    };

    const FP = [['Little', 50, 105, 5], ['Ring', 105, 165, 4], ['Middle', 165, 235, 3], ['Index', 235, 305, 2]];
    const FD = [['Index', 125, 200, 2], ['Middle', 200, 275, 3], ['Ring', 275, 335, 4], ['Little', 335, 380, 5]];

    R.palm.b.splice(3, 0, ...FP.map(f => [
        f[0] + ' finger · phalanges & flexor tendons',
        f[1], 0, f[2], 322,
        f[0] + ' finger: proximal, middle and distal phalanges with flexor digitorum superficialis and profundus tendons. Correlates with Flex Sensor ' + f[3] + '.'
    ]));

    R.dorsal.b.splice(1, 0, ...FD.map(f => [
        f[0] + ' finger · phalanges & extensor tendon',
        f[1], 0, f[2], 285,
        f[0] + ' finger: three phalanges covered by dorsal extensor hood; extensor digitorum straightens finger. Correlates with Flex Sensor ' + f[3] + '.'
    ]));

    const TAG = {
        m: 'Muscle',
        b: 'Bone / Tendon',
        c: 'Cartilage / Sheath',
        s: 'Skin'
    };

    class HandAnatomyAtlas {
        constructor() {
            this.initialized = false;
            this.building = false;
            this.scene = null;
            this.camera = null;
            this.renderer = null;
            this.ctl = null;
            this.group = null;
            this.layers = [];
            this.cores = [];
            this.skinMats = [];
            this.FILL = {};
            this.V = { palm: { ax: 500 }, dorsal: { ax: 700 } };
            this.vis = { s: 1, b: 1, m: 1, c: 1 };
            this.skinOp = 0.8;
            this.sel = null;
            this.hp = null;
            this.hn = null;
            this.vt = null;
            this.ray = new THREE.Raycaster();
            this.mv = new THREE.Vector2();
            this.mark = null;
            this.matCore = [];
            this.parts = [];
            this.searchTimer = null;
            this.rafId = null;
            this.resizeObserver = null;

            // Flatten dictionary for instant search
            for (const key in R) {
                for (const type in R[key]) {
                    R[key][type].forEach(r => {
                        if (r[0] !== 'Bones & tendons') {
                            this.parts.push({ key, type, r });
                        }
                    });
                }
            }
        }

        el(id) {
            return document.getElementById(id);
        }

        init() {
            const canvas = this.el('atlasCanvas');
            if (!canvas) return;

            // Hook UI event listeners
            this.bindUI();

            // Set up ResizeObserver on stage container
            const stage = this.el('atlasStage');
            if (stage && typeof ResizeObserver !== 'undefined') {
                this.resizeObserver = new ResizeObserver(() => {
                    const tab = this.el('tab-glossary');
                    if (tab && tab.classList.contains('active')) {
                        this.resize();
                    }
                });
                this.resizeObserver.observe(stage);
            }

            // If tab is currently active on page load, build immediately
            const tab = this.el('tab-glossary');
            if (tab && tab.classList.contains('active')) {
                this.renderList();
            }
        }

        bindUI() {
            // View direction buttons
            document.querySelectorAll('[data-atlas-view]').forEach(btn => {
                btn.addEventListener('click', () => {
                    const view = btn.dataset.atlasView;
                    this.preset(view);
                    document.querySelectorAll('[data-atlas-view]').forEach(b => {
                        b.setAttribute('aria-pressed', String(b === btn));
                        b.classList.toggle('active', b === btn);
                    });
                });
            });

            // Spin button
            const spinBtn = this.el('atlasSpin');
            if (spinBtn) {
                spinBtn.addEventListener('click', () => {
                    if (this.ctl) {
                        this.ctl.autoRotate = !this.ctl.autoRotate;
                        this.ctl.autoRotateSpeed = 2.5;
                        spinBtn.classList.toggle('active', this.ctl.autoRotate);
                        spinBtn.setAttribute('aria-pressed', String(this.ctl.autoRotate));
                    }
                });
            }

            // Layer checkboxes
            document.querySelectorAll('#tab-glossary input[data-k]').forEach(cb => {
                cb.addEventListener('change', () => {
                    this.vis[cb.dataset.k] = cb.checked ? 1 : 0;
                    this.apply();
                });
            });

            // Skin opacity slider
            const opSlider = this.el('atlasSkinOpacity');
            if (opSlider) {
                opSlider.addEventListener('input', () => {
                    this.skinOp = opSlider.value / 100;
                    this.skinMats.forEach(m => m.opacity = this.skinOp);
                    if (this.layers.length) this.apply();
                });
            }

            // Quick isolate presets
            const PR = {
                all:  [1, 1, 1, 1, 0.8],
                skin: [1, 0, 0, 0, 1.0],
                ana:  [0, 1, 1, 1, 1.0],
                b:    [0, 1, 0, 0, 1.0],
                m:    [0, 0, 1, 0, 1.0]
            };

            document.querySelectorAll('[data-atlas-preset]').forEach(btn => {
                btn.addEventListener('click', () => {
                    const pr = PR[btn.dataset.atlasPreset];
                    if (!pr) return;
                    ['s', 'b', 'm', 'c'].forEach((k, i) => this.vis[k] = pr[i]);
                    if (opSlider) {
                        opSlider.value = pr[4] * 100;
                    }
                    this.skinOp = pr[4];
                    this.skinMats.forEach(m => m.opacity = this.skinOp);
                    this.apply();
                    document.querySelectorAll('[data-atlas-preset]').forEach(b => {
                        b.classList.toggle('active', b === btn);
                    });
                });
            });

            // Search input
            const searchInput = this.el('atlasSearch');
            if (searchInput) {
                searchInput.addEventListener('input', () => {
                    clearTimeout(this.searchTimer);
                    this.hideSearchDropdown();
                    this.searchTimer = setTimeout(() => this.showSearchDropdown(), 250);
                });
                searchInput.addEventListener('keydown', e => {
                    if (e.key === 'Enter') {
                        clearTimeout(this.searchTimer);
                        this.showSearchDropdown();
                    } else if (e.key === 'Escape') {
                        clearTimeout(this.searchTimer);
                        this.hideSearchDropdown();
                    }
                });
            }

            // Quick search chips
            document.querySelectorAll('[data-search-chip]').forEach(chip => {
                chip.addEventListener('click', () => {
                    const term = chip.dataset.searchChip;
                    if (searchInput) {
                        searchInput.value = term;
                        this.showSearchDropdown();
                    }
                });
            });

            // Camera buttons
            const zoomIn = this.el('atlasZoomIn');
            if (zoomIn) zoomIn.addEventListener('click', () => this.zoom(0.85));

            const zoomOut = this.el('atlasZoomOut');
            if (zoomOut) zoomOut.addEventListener('click', () => this.zoom(1.18));

            const resetBtn = this.el('atlasReset');
            if (resetBtn) resetBtn.addEventListener('click', () => this.preset('palm'));

            // Stage canvas pointer events
            const canvas = this.el('atlasCanvas');
            let d0 = null;
            canvas.addEventListener('pointerdown', e => {
                d0 = [e.clientX, e.clientY];
            });
            canvas.addEventListener('pointerup', e => {
                if (!d0 || Math.hypot(e.clientX - d0[0], e.clientY - d0[1]) > 6) return;
                this.onCanvasClick(e);
            });

            // Window resize
            window.addEventListener('resize', () => {
                const tab = this.el('tab-glossary');
                if (tab && tab.classList.contains('active')) {
                    this.resize();
                }
            });
        }

        async renderList() {
            if (this.initialized) {
                this.resize();
                return;
            }
            if (this.building) return;
            this.building = true;

            const notice = this.el('atlasNotice');
            if (notice) notice.style.display = 'flex';

            try {
                await this.build();
                this.initialized = true;
                if (notice) notice.style.display = 'none';
                this.resize();

                // Select default prominent structure (Adductor pollicis)
                const def = this.parts.find(p => p.r[0].includes('Adductor')) || this.parts[0];
                if (def) this.goTo(def);

                // Start render loop
                this.startLoop();
            } catch (err) {
                console.error('Error building 3D Hand Atlas:', err);
                if (notice) {
                    notice.innerHTML = '<strong>Unable to render 3D model</strong><p>' + (err.message || 'WebGL context error') + '</p>';
                }
            } finally {
                this.building = false;
            }
        }

        zoom(factor) {
            if (!this.camera) return;
            this.camera.position.multiplyScalar(factor);
            if (this.ctl) this.ctl.update();
        }

        preset(name) {
            const VW = {
                palm: [0, 0, 54],
                back: [0, 0, -54],
                side: [54, 0, 0],
                angle: [34, 10, 40]
            };
            const target = VW[name] || VW.palm;
            this.vt = new THREE.Vector3(...target);
        }

        solid() {
            return this.vis.s && this.skinOp >= 0.99;
        }

        apply() {
            this.layers.forEach(l => {
                l.m.visible = l.type !== 's' && !!this.vis[l.type] && !this.solid();
            });
            this.coreStyle();
            document.querySelectorAll('#tab-glossary input[data-k]').forEach(cb => {
                cb.checked = !!this.vis[cb.dataset.k];
            });
            if (this.sel && ((!this.vis[this.sel.type] && this.sel.type !== 's') || (this.solid() && this.sel.type !== 's'))) {
                this.pick(null);
            }
        }

        coreStyle() {
            if (!this.FILL.palm) return;
            this.cores.forEach(c => c.visible = !!this.vis.s);
            this.matCore.forEach((m, i) => {
                m.map = this.FILL[i ? 'dorsal' : 'palm'].skin;
                m.color.set(0xffffff);
                const t = this.skinOp < 0.99;
                m.transparent = t;
                m.opacity = this.skinOp;
                m.depthWrite = !t;
                m.needsUpdate = true;
            });
        }

        async build() {
            const canvas = this.el('atlasCanvas');
            const stage = this.el('atlasStage');
            const width = stage.clientWidth || 800;
            const height = stage.clientHeight || 560;

            this.scene = new THREE.Scene();
            this.camera = new THREE.PerspectiveCamera(32, width / height, 0.1, 300);
            this.camera.position.set(0, 0, 54);
            this.scene.add(this.camera);

            this.scene.add(new THREE.AmbientLight(0xffffff, 0.48));
            const keyLight = new THREE.DirectionalLight(0xffffff, 0.65);
            keyLight.position.set(0, 0, 1);
            this.camera.add(keyLight);
            const fillLight = new THREE.DirectionalLight(0xfff4e6, 0.24);
            fillLight.position.set(-20, 25, 35);
            this.scene.add(fillLight);

            this.renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
            this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
            this.renderer.setSize(width, height, false);

            if (typeof THREE.OrbitControls !== 'undefined') {
                this.ctl = new THREE.OrbitControls(this.camera, this.renderer.domElement);
                this.ctl.enableDamping = true;
                this.ctl.dampingFactor = 0.08;
                this.ctl.minDistance = 15;
                this.ctl.maxDistance = 110;
                this.ctl.update();
            }

            const loadImage = src => new Promise((resolve, reject) => {
                const img = new Image();
                img.onload = () => resolve(img);
                img.onerror = reject;
                img.src = src;
            });

            const [palmImg, dorsalImg] = await Promise.all([loadImage(IM.palm), loadImage(IM.dorsal)]);

            // Helper: Canvas texture with high anisotropy
            const tex = cv => {
                const t = new THREE.CanvasTexture(cv);
                t.anisotropy = 8;
                return t;
            };

            // Preparation: Color channel slicing
            const prep = img => {
                const c = document.createElement('canvas');
                c.width = W; c.height = H;
                const x = c.getContext('2d');
                x.drawImage(img, 0, 0);
                const d = x.getImageData(0, 0, W, H).data;
                const n = W * H;
                const cl = {
                    m: x.createImageData(W, H),
                    b: x.createImageData(W, H),
                    c: x.createImageData(W, H),
                    s: x.createImageData(W, H)
                };
                const sk = x.createImageData(W, H);

                const sm = document.createElement('canvas');
                sm.width = 56; sm.height = 72;
                const sx = sm.getContext('2d');
                sx.imageSmoothingQuality = 'high';
                sx.drawImage(c, 0, 0, 56, 72);

                const bl = document.createElement('canvas');
                bl.width = W; bl.height = H;
                const bx = bl.getContext('2d');
                bx.imageSmoothingQuality = 'high';
                bx.drawImage(sm, 0, 0, W, H);
                const bd = bx.getImageData(0, 0, W, H).data;

                for (let i = 0; i < n; i++) {
                    const o = i * 4, r = d[o], g = d[o + 1], b = d[o + 2], a = d[o + 3];
                    if (a < 6) continue;
                    const mx = Math.max(r, g, b), mn = Math.min(r, g, b), sat = (mx - mn) / mx;
                    let k;
                    if (r > g * 1.3 && r > b * 1.3 && r > 85) k = 'm';
                    else if (b > r + 14 && b >= g - 4) k = 'c';
                    else if (sat < 0.075) k = 's';
                    else k = 'b';

                    const bb = Math.min(1, Math.max(0, (bd[o + 3] / 255 - 0.5) / 0.35));
                    const f = bb * bb * (3 - 2 * bb);
                    const t_arr = cl[k].data;
                    t_arr[o] = r; t_arr[o + 1] = g; t_arr[o + 2] = b;
                    t_arr[o + 3] = k === 's' ? a * f : a;

                    const lum = (0.3 * bd[o] + 0.59 * bd[o + 1] + 0.11 * bd[o + 2]) / 255;
                    const e = (0.7 + 0.3 * Math.min(1, bd[o + 3] / 200)) * (0.98 + 0.02 * lum);
                    const s_arr = sk.data;
                    s_arr[o] = 232 * e; s_arr[o + 1] = 184 * e; s_arr[o + 2] = 156 * e;
                    s_arr[o + 3] = a * Math.min(1, f * 3);
                }
                return { d, cl, sk };
            };

            // Solid volumetric organic hand generator
            const buildBody = (P, D) => {
                const ST = 4, XMIN = -720, gx = 411, gy = H / ST, gw = gx + 1, gh = gy + 15;
                const m = new Float32Array(gw * gh);
                for (let j = 0; j < gh; j++) {
                    const y = Math.min(j * ST, H - 30);
                    for (let i = 0; i < gw; i++) {
                        const xp = XMIN + i * ST, pp = Math.round(xp + 500);
                        let c = 0;
                        for (let a = -1; a <= 1; a++) {
                            for (let b = -1; b <= 1; b++) {
                                const px = pp + a * ST / 2;
                                const py = Math.min(H - 1, Math.max(0, Math.round(y + b * ST / 2)));
                                if (py <= 1736 && px >= 0 && px < W && P.d[(py * W + Math.round(px)) * 4 + 3] > 128) c++;
                            }
                        }
                        m[j * gw + i] = c / 9;
                    }
                }

                for (let p = 0; p < 1; p++) {
                    const c = m.slice();
                    for (let j = 1; j < gh - 1; j++) {
                        for (let i = 1; i < gw - 1; i++) {
                            const k = j * gw + i;
                            let s = 0;
                            for (let a = -1; a <= 1; a++) for (let b = -1; b <= 1; b++) s += c[k + a * gw + b];
                            m[k] = s / 9;
                        }
                    }
                }

                const sm0 = m.slice();
                for (let k = 0; k < m.length; k++) m[k] = m[k] > 0.5 ? 1e9 : 0;
                const g = (i, j) => (i < 0 || j < 0 || i >= gw || j >= gh) ? 0 : m[j * gw + i];

                for (let j = 0; j < gh; j++) {
                    for (let i = 0; i < gw; i++) {
                        const k = j * gw + i;
                        if (m[k] > 0) m[k] = Math.min(m[k], g(i - 1, j) + 1, g(i, j - 1) + 1, g(i - 1, j - 1) + 1.41, g(i + 1, j - 1) + 1.41);
                    }
                }
                for (let j = gh - 1; j >= 0; j--) {
                    for (let i = gw - 1; i >= 0; i--) {
                        const k = j * gw + i;
                        if (m[k] > 0) m[k] = Math.min(m[k], g(i + 1, j) + 1, g(i, j + 1) + 1, g(i + 1, j + 1) + 1.41, g(i - 1, j + 1) + 1.41);
                    }
                }
                for (let p = 0; p < 22; p++) {
                    const c = m.slice();
                    for (let j = 1; j < gh - 1; j++) {
                        for (let i = 1; i < gw - 1; i++) {
                            const k = j * gw + i;
                            if (c[k] > 0) {
                                let s = 0;
                                for (let a = -1; a <= 1; a++) for (let b = -1; b <= 1; b++) s += c[k + a * gw + b];
                                m[k] = s / 9;
                            }
                        }
                    }
                }

                const nv = gw * (gy + 1), hh = new Float32Array(nv), rm = new Float32Array(nv), eg = new Float32Array(nv), idx = [];
                for (let j = 0; j <= gy; j++) {
                    for (let i = 0; i < gw; i++) {
                        const dp = m[j * gw + i] * ST;
                        let h = 0;
                        if (dp > 0) {
                            const q = Math.min(dp, 170) / 170;
                            h = 95 * Math.sqrt(1 - (1 - q) * (1 - q)) + 70 * Math.min(1, Math.max(0, (dp - 100) / 250));
                        }
                        hh[j * gw + i] = h;
                        const k = j * gw + i;
                        rm[k] = Math.min(0.5, Math.max(-0.5, sm0[k] - 0.5));
                        const u = Math.min(1, dp / 36);
                        eg[k] = 1 - u * u * (3 - 2 * u);
                    }
                }

                for (let j = 0; j < gy; j++) {
                    for (let i = 0; i < gx; i++) {
                        const a = j * gw + i, b = a + 1, c = a + gw, e = c + 1;
                        if (hh[a] > 0 || hh[b] > 0 || hh[c] > 0 || hh[e] > 0) idx.push(a, b, c, b, e, c);
                    }
                }

                const posT = new Float32Array(nv * 3), posB = new Float32Array(nv * 3);
                const uvT = new Float32Array(nv * 2), uvB = new Float32Array(nv * 2);

                for (let j = 0; j <= gy; j++) {
                    for (let i = 0; i < gw; i++) {
                        const k = j * gw + i, xp = XMIN + i * ST, x = xp * U, y = (H / 2 - j * ST) * U;
                        posT[k * 3] = posB[k * 3] = x;
                        posT[k * 3 + 1] = posB[k * 3 + 1] = y;
                        posT[k * 3 + 2] = hh[k] * U;
                        posB[k * 3 + 2] = -hh[k] * U;
                        uvT[k * 2] = (xp + 500) / W;
                        uvB[k * 2] = (700 - xp) / W;
                        uvT[k * 2 + 1] = uvB[k * 2 + 1] = 1 - j * ST / H;
                    }
                }

                const top = [], bot = [];
                for (let t = 0; t < idx.length; t += 3) {
                    top.push(idx[t], idx[t + 2], idx[t + 1]);
                    bot.push(idx[t], idx[t + 1], idx[t + 2]);
                }

                const P2 = new Float32Array(nv * 6);
                P2.set(posT, 0); P2.set(posB, nv * 3);
                const ci = top.slice();
                for (let t = 0; t < bot.length; t++) {
                    const k = bot[t];
                    ci.push(hh[k] > 0 ? nv + k : k);
                }

                const cg = new THREE.BufferGeometry();
                cg.setAttribute('position', new THREE.BufferAttribute(P2, 3));
                cg.setIndex(ci);
                cg.computeVertexNormals();

                const N = cg.attributes.normal.array;
                const uvC = new Float32Array(nv * 4);
                uvC.set(uvT, 0); uvC.set(uvB, nv * 2);
                cg.setAttribute('uv', new THREE.BufferAttribute(uvC, 2));

                const r2 = new Float32Array(nv * 2), e2 = new Float32Array(nv * 2);
                r2.set(rm, 0); r2.set(rm, nv);
                e2.set(eg, 0); e2.set(eg, nv);
                cg.setAttribute('rim', new THREE.BufferAttribute(r2, 1));
                cg.setAttribute('edge', new THREE.BufferAttribute(e2, 1));
                cg.addGroup(0, top.length, 0);
                cg.addGroup(top.length, bot.length, 1);
                cg.computeBoundingSphere();

                const nT = new Float32Array(nv * 3), nB = new Float32Array(nv * 3);
                for (let k = 0; k < nv; k++) {
                    for (let c = 0; c < 3; c++) {
                        nT[k * 3 + c] = N[k * 3 + c];
                        nB[k * 3 + c] = hh[k] > 0 ? N[(nv + k) * 3 + c] : N[k * 3 + c];
                    }
                }

                const mk = (pos, uv, ix, nn) => {
                    const ge = new THREE.BufferGeometry();
                    ge.setAttribute('rim', new THREE.BufferAttribute(rm, 1));
                    ge.setAttribute('position', new THREE.BufferAttribute(pos, 3));
                    ge.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
                    ge.setAttribute('normal', new THREE.BufferAttribute(nn, 3));
                    ge.setIndex(ix);
                    ge.computeBoundingSphere();
                    return ge;
                };

                return { core: cg, palm: mk(posT, uvT, top, nT), dorsal: mk(posB, uvB, bot, nB) };
            };

            // Custom Shaders
            const shellFix = m => {
                m.onBeforeCompile = s => {
                    s.vertexShader = s.vertexShader
                        .replace('#include <common>', '#include <common>\nattribute float rim;\nattribute float edge;\nvarying float vRim;\nvarying float vEdge;\nvarying float vWV;')
                        .replace('#include <begin_vertex>', '#include <begin_vertex>\nvRim=rim;vEdge=edge;')
                        .replace('#include <project_vertex>', '#include <project_vertex>\nvWV=abs(dot(normalize(normalMatrix*normal),normalize(-mvPosition.xyz)));');
                    s.fragmentShader = s.fragmentShader
                        .replace('#include <common>', '#include <common>\nvarying float vRim;\nvarying float vEdge;\nvarying float vWV;')
                        .replace('#include <map_fragment>', '#include <map_fragment>\ndiffuseColor.rgb=mix(diffuseColor.rgb,vec3(.86,.67,.57),vEdge*vEdge*vEdge*.8);if(vRim<0.&&vWV<.6)discard;');
                };
                return m;
            };

            const rimFix = m => {
                m.onBeforeCompile = s => {
                    s.vertexShader = s.vertexShader
                        .replace('#include <common>', '#include <common>\nattribute float rim;\nvarying float vRim;')
                        .replace('#include <begin_vertex>', '#include <begin_vertex>\nvRim=rim;');
                    s.fragmentShader = s.fragmentShader
                        .replace('#include <common>', '#include <common>\nvarying float vRim;')
                        .replace('#include <alphatest_fragment>', 'diffuseColor.a*=clamp(vRim*12.,0.,1.);\n#include <alphatest_fragment>');
                };
                return m;
            };

            const polyM = (o, f) => rimFix(new THREE.MeshLambertMaterial(Object.assign({
                polygonOffset: true,
                polygonOffsetFactor: -f,
                polygonOffsetUnits: -f
            }, o)));

            const sh = () => shellFix(new THREE.MeshLambertMaterial({
                color: 0xffffff,
                polygonOffset: true,
                polygonOffsetFactor: -6,
                polygonOffsetUnits: -6
            }));

            this.matCore = [sh(), sh()];

            // Side texture fill
            const fillTex = arrs => {
                const GW = 350, GH = 450, n = GW * GH;
                const sr = new Float32Array(n), sg = new Float32Array(n), sb = new Float32Array(n), sa = new Float32Array(n);
                for (const d of arrs) {
                    for (let y = 0; y < H; y++) {
                        const row = (y >> 2) * GW;
                        for (let x = 0; x < W; x++) {
                            const o = (y * W + x) * 4;
                            if (d[o + 3] > 40) {
                                const c = row + (x >> 2);
                                sr[c] += d[o]; sg[c] += d[o + 1]; sb[c] += d[o + 2]; sa[c]++;
                            }
                        }
                    }
                }
                const r = new Float32Array(n), g = new Float32Array(n), b = new Float32Array(n), ok = new Uint8Array(n);
                for (let i = 0; i < n; i++) {
                    if (sa[i] >= 5) {
                        r[i] = sr[i] / sa[i]; g[i] = sg[i] / sa[i]; b[i] = sb[i] / sa[i]; ok[i] = 1;
                    }
                }
                for (let it = 0; it < 45; it++) {
                    const nk = ok.slice();
                    for (let y = 0; y < GH; y++) {
                        for (let x = 0; x < GW; x++) {
                            const i = y * GW + x;
                            if (ok[i]) continue;
                            let R_ = 0, G_ = 0, B_ = 0, c = 0;
                            for (const j of [x > 0 ? i - 1 : -1, x < GW - 1 ? i + 1 : -1, y > 0 ? i - GW : -1, y < GH - 1 ? i + GW : -1]) {
                                if (j >= 0 && ok[j]) {
                                    R_ += r[j]; G_ += g[j]; B_ += b[j]; c++;
                                }
                            }
                            if (c) {
                                r[i] = R_ / c; g[i] = G_ / c; b[i] = B_ / c; nk[i] = 1;
                            }
                        }
                    }
                    ok.set(nk);
                }
                const cv = document.createElement('canvas');
                cv.width = GW; cv.height = GH;
                const cx = cv.getContext('2d');
                const im = cx.createImageData(GW, GH);
                for (let i = 0; i < n; i++) {
                    im.data[i * 4] = ok[i] ? r[i] : 200;
                    im.data[i * 4 + 1] = ok[i] ? g[i] : 190;
                    im.data[i * 4 + 2] = ok[i] ? b[i] : 170;
                    im.data[i * 4 + 3] = 255;
                }
                cx.putImageData(im, 0, 0);
                return tex(cv);
            };

            // Build layers and scene graph
            const P = prep(palmImg), D = prep(dorsalImg);
            const G = buildBody(P, D);

            [['palm', P], ['dorsal', D]].forEach(([key, A]) => {
                const geo = G[key];
                this.FILL[key] = { skin: fillTex([A.sk.data]) };
                const cv = document.createElement('canvas');
                cv.width = W; cv.height = H;
                const cx = cv.getContext('2d');
                cx.imageSmoothingQuality = 'high';
                cx.drawImage(this.FILL[key].skin.image, 0, 0, W, H);
                const c2 = document.createElement('canvas');
                c2.width = W; c2.height = H;
                c2.getContext('2d').putImageData(A.sk, 0, 0);
                cx.drawImage(c2, 0, 0);
                this.FILL[key].skin = tex(cv);

                const put = (imd, mat) => {
                    const c3 = document.createElement('canvas');
                    c3.width = W; c3.height = H;
                    c3.getContext('2d').putImageData(imd, 0, 0);
                    mat.map = tex(c3);
                    const m = new THREE.Mesh(geo, mat);
                    m.raycast = () => {};
                    this.scene.add(m);
                    return m;
                };

                const f = { s: 1, c: 2, b: 3, m: 4 };
                for (const k in A.cl) {
                    const m = put(A.cl[k], polyM({ alphaTest: 0.1 }, f[k]));
                    this.layers.push({ m, type: k, key, data: A.cl[k].data });
                }

                const hc = document.createElement('canvas');
                hc.width = W; hc.height = H;
                const ht = tex(hc);
                const hm = put(A.cl.s, rimFix(new THREE.MeshBasicMaterial({
                    transparent: true,
                    depthWrite: false,
                    alphaTest: 0.01,
                    polygonOffset: true,
                    polygonOffsetFactor: -8,
                    polygonOffsetUnits: -8
                })));
                hm.material.map = ht;
                hm.visible = false;
                hm.renderOrder = 5;
                Object.assign(this.V[key], { hm, hc, ht });
            });

            const cm = new THREE.Mesh(G.core, this.matCore);
            this.scene.add(cm);
            this.cores.push(cm);

            // 3D Pin Target Marker Sprite
            const markerCanvas = document.createElement('canvas');
            markerCanvas.width = markerCanvas.height = 64;
            const mx = markerCanvas.getContext('2d');
            mx.lineWidth = 7;
            mx.strokeStyle = '#ffd23f';
            mx.beginPath();
            mx.arc(32, 32, 24, 0, 2 * Math.PI);
            mx.stroke();
            mx.strokeStyle = '#6A6223';
            mx.lineWidth = 2.5;
            mx.beginPath();
            mx.arc(32, 32, 28, 0, 2 * Math.PI);
            mx.stroke();

            this.mark = new THREE.Sprite(new THREE.SpriteMaterial({
                map: new THREE.CanvasTexture(markerCanvas),
                depthTest: false
            }));
            this.mark.scale.set(1.4, 1.4, 1);
            this.mark.visible = false;
            this.mark.renderOrder = 9;
            this.scene.add(this.mark);

            this.apply();
        }

        clearHL() {
            for (const k in this.V) {
                if (this.V[k].hm) this.V[k].hm.visible = false;
            }
        }

        highlight(key, type, b) {
            this.clearHL();
            if (type === 's') return;
            const l = this.layers.find(ly => ly.key === key && ly.type === type && ly.data);
            const v = this.V[key];
            if (!l || !v || !v.hc) return;

            const x0 = Math.max(0, Math.floor(b[1] * K));
            const y0 = Math.max(0, Math.floor(b[2] * K));
            const x1 = Math.min(W, Math.ceil(b[3] * K));
            const y1 = Math.min(H, Math.ceil(b[4] * K));
            const w = x1 - x0, h = y1 - y0;
            if (w <= 0 || h <= 0) return;

            const ctx = v.hc.getContext('2d');
            const im = ctx.createImageData(w, h);
            for (let y = 0; y < h; y++) {
                for (let x = 0; x < w; x++) {
                    const s = ((y + y0) * W + x + x0) * 4;
                    const o = (y * w + x) * 4;
                    const a = l.data[s + 3];
                    if (a > 40) {
                        im.data[o] = 255;
                        im.data[o + 1] = 205;
                        im.data[o + 2] = 40;
                        im.data[o + 3] = Math.round(a * 0.75);
                    }
                }
            }
            ctx.clearRect(0, 0, W, H);
            ctx.putImageData(im, x0, y0);
            v.ht.needsUpdate = true;
            v.hm.visible = true;
        }

        pick(o) {
            this.sel = o;
            const lbl = this.el('atlasFloatingLabel');
            const nameEl = this.el('atlasSelectedName');
            const descEl = this.el('atlasSelectedDescription');
            const typeEl = this.el('atlasSelectedType');
            const sideEl = this.el('atlasSelectedSide');

            if (!o) {
                this.clearHL();
                if (lbl) lbl.style.display = 'none';
                if (this.mark) this.mark.visible = false;
                if (nameEl) nameEl.textContent = 'Tap any structure on the hand';
                if (descEl) descEl.textContent = 'Rotate the 3D hand and click any muscle, tendon, bone, or joint — or use the search below to isolate and fly the camera directly to it.';
                if (typeEl) typeEl.textContent = 'ANATOMICAL STRUCTURE';
                if (sideEl) sideEl.textContent = '3D MODEL';
                return;
            }

            const isPalmar = o.key === 'palm';
            const catName = TAG[o.type] || 'Structure';

            if (typeEl) typeEl.textContent = (catName + ' · ' + (isPalmar ? 'Palmar Aspect' : 'Dorsal Aspect')).toUpperCase();
            if (sideEl) sideEl.textContent = isPalmar ? 'PALM SIDE' : 'BACK OF HAND';
            if (nameEl) nameEl.textContent = o.name;
            if (descEl) descEl.textContent = o.info;
            if (lbl) lbl.textContent = o.name;

            if (this.hp) {
                this.mark.position.copy(this.hp);
                this.mark.visible = true;
            }
            this.highlight(o.key, o.type, o.box);
        }

        region(key, type, px, py) {
            const list = R[key][type];
            const rx = px / K, ry = py / K;
            return list.find(a => rx >= a[1] && rx <= a[3] && ry >= a[2] && ry <= a[4]) || list[list.length - 1];
        }

        onCanvasClick(e) {
            if (!this.cores.length || !this.camera || !this.renderer) return;
            const canvas = this.el('atlasCanvas');
            const box = canvas.getBoundingClientRect();
            this.mv.set(((e.clientX - box.left) / box.width) * 2 - 1, -(((e.clientY - box.top) / box.height) * 2 - 1));
            this.ray.setFromCamera(this.mv, this.camera);

            const hits = this.ray.intersectObjects(this.cores);
            if (!hits.length) {
                this.pick(null);
                return;
            }

            const h = hits[0];
            const key = h.face.normal.z >= 0 ? 'palm' : 'dorsal';
            const px = Math.floor(h.uv.x * W);
            const py = Math.floor((1 - h.uv.y) * H);
            const inb = px >= 0 && px < W && py >= 0 && py < H;

            let type = null;
            if (inb) {
                for (const t of ['m', 'c', 'b', 's']) {
                    const l = this.layers.find(ly => ly.key === key && ly.type === t && ly.data);
                    if (this.vis[t] && !(this.solid() && t !== 's') && l && l.data[(py * W + px) * 4 + 3] > 60) {
                        type = t;
                        break;
                    }
                }
            }
            if (!type && this.vis.s) type = 's';
            if (!type) {
                this.pick(null);
                return;
            }

            this.hp = h.point.clone();
            this.hn = h.face.normal.clone().transformDirection(h.object.matrixWorld);
            const reg = this.region(key, type, inb ? px : 0, inb ? py : 0);
            this.pick({
                type,
                key,
                name: reg[0],
                info: reg[5],
                box: reg
            });
        }

        hideSearchDropdown() {
            const lst = this.el('atlasSearchDropdown');
            if (lst) {
                lst.style.display = 'none';
                lst.innerHTML = '';
            }
        }

        showSearchDropdown() {
            const input = this.el('atlasSearch');
            const lst = this.el('atlasSearchDropdown');
            if (!input || !lst) return;

            const q = input.value.trim().toLowerCase();
            this.hideSearchDropdown();
            if (!q) return;

            const words = q.split(/\s+/);
            const results = this.parts.filter(p => {
                const h = (p.r[0] + ' ' + p.r[5] + ' ' + TAG[p.type] + ' ' + (p.key === 'palm' ? 'palm front' : 'back dorsal')).toLowerCase();
                return words.every(w => h.includes(w));
            });

            if (!results.length) {
                const li = document.createElement('li');
                li.className = 'atlas-search-empty';
                li.textContent = 'No matching anatomical structures';
                lst.appendChild(li);
            } else {
                results.slice(0, 10).forEach(p => {
                    const li = document.createElement('li');
                    li.className = 'atlas-search-item';
                    const title = document.createElement('div');
                    title.className = 'atlas-search-title';
                    title.textContent = p.r[0];
                    const meta = document.createElement('small');
                    meta.className = 'atlas-search-meta';
                    meta.textContent = (TAG[p.type] || 'Structure') + ' · ' + (p.key === 'palm' ? 'Palm Side' : 'Back of Hand');
                    li.appendChild(title);
                    li.appendChild(meta);
                    li.addEventListener('click', () => {
                        input.value = p.r[0];
                        this.hideSearchDropdown();
                        this.goTo(p);
                    });
                    lst.appendChild(li);
                });
            }
            lst.style.display = 'block';
        }

        goTo(p) {
            const l = this.layers.find(ly => ly.key === p.key && ly.type === p.type && ly.data);
            if (!l) return;

            this.vis[p.type] = 1;
            this.apply();

            const isPalmar = p.key === 'palm';
            this.vt = new THREE.Vector3(0, 0, isPalmar ? 54 : -54);

            const b = p.r;
            const cx = (b[1] + b[3]) / 2 * K;
            const cy = (b[2] + b[4]) / 2 * K;
            let best = 1e12, bx = cx, by = cy;

            for (let y = Math.max(0, b[2] * K | 0); y < Math.min(H, b[4] * K); y += 6) {
                for (let x = Math.max(0, b[1] * K | 0); x < Math.min(W, b[3] * K); x += 6) {
                    if (l.data[(y * W + x) * 4 + 3] > 60) {
                        const dd = (x - cx) ** 2 + (y - cy) ** 2;
                        if (dd < best) {
                            best = dd; bx = x; by = y;
                        }
                    }
                }
            }

            const wx = (isPalmar ? bx - 500 : 700 - bx) * U;
            const wy = (H / 2 - by) * U;
            const z0 = isPalmar ? 60 : -60;

            this.ray.set(new THREE.Vector3(wx, wy, z0), new THREE.Vector3(0, 0, -Math.sign(z0)));
            const hits = this.ray.intersectObjects(this.cores);
            this.hp = hits.length ? hits[0].point.clone() : new THREE.Vector3(wx, wy, isPalmar ? 2 : -2);
            this.hn = new THREE.Vector3(0, 0, isPalmar ? 1 : -1);

            this.pick({
                type: p.type,
                key: p.key,
                name: b[0],
                info: b[5],
                box: b
            });
        }

        resize() {
            const stage = this.el('atlasStage');
            if (!stage || !this.renderer || !this.camera) return;
            const w = stage.clientWidth;
            const h = stage.clientHeight;
            if (!w || !h) return;
            this.camera.aspect = w / h;
            this.camera.updateProjectionMatrix();
            this.renderer.setSize(w, h, false);
        }

        startLoop() {
            if (this.rafId) cancelAnimationFrame(this.rafId);

            const tick = () => {
                this.rafId = requestAnimationFrame(tick);
                const tab = this.el('tab-glossary');
                if (!tab || !tab.classList.contains('active')) return;

                if (this.vt) {
                    this.camera.position.lerp(this.vt, 0.1);
                    if (this.camera.position.distanceTo(this.vt) < 0.2) this.vt = null;
                }

                if (this.ctl) this.ctl.update();

                // Position floating 3D screen label
                const lbl = this.el('atlasFloatingLabel');
                if (this.sel && this.hp && this.hn && lbl) {
                    const ok = this.hn.dot(this.camera.position.clone().sub(this.hp)) > 0;
                    lbl.style.display = ok ? 'block' : 'none';
                    if (this.mark) this.mark.visible = !!ok;
                    if (ok) {
                        const stage = this.el('atlasStage');
                        const p = this.hp.clone().project(this.camera);
                        const sw = stage.clientWidth, sh = stage.clientHeight;
                        lbl.style.left = ((p.x + 1) / 2 * sw) + 'px';
                        lbl.style.top = ((1 - p.y) / 2 * sh) + 'px';
                    }
                }

                if (this.renderer && this.scene && this.camera) {
                    this.renderer.render(this.scene, this.camera);
                }
            };
            tick();
        }

        updateTelemetry(state) {
            // Multi-channel telemetry hook
        }

        updateLanguage() {
            // Multi-language update hook
        }
    }

    const handGlossary = new HandAnatomyAtlas();
    window.handGlossary = handGlossary;

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => handGlossary.init());
    } else {
        handGlossary.init();
    }
})();
